import axios from 'axios';
import EventEmitter from 'eventemitter3';

import { IServerEvents } from './events';
import { IResumeRequest } from './requests/resume';
import { IBeginRequest } from './requests/begin';
import { IContinueRequest } from './requests/continue';
import { IGameServerResponse } from './response/response';
import { RESULT_CODES } from './result-codes';

// adds $response data to the window for our Automated testing solution
declare global {
    interface Window {
        $response: IGameServerResponse;
    }
}

export class ReqResServer<TBaseResponse extends IGameServerResponse = IGameServerResponse> extends EventEmitter<IServerEvents<TBaseResponse>> {
    protected realityCheckDuration: number = 3600; // 3600 seconds = 60 minutes

    constructor(options?: { realityCheckDuration?: number }) {
        super();
        if (options?.realityCheckDuration) {
            this.realityCheckDuration = options.realityCheckDuration;
        }
    }

    protected makeRequest<TRequest extends IBeginRequest | IResumeRequest | IContinueRequest, TResponse extends TBaseResponse>(url: string, body: TRequest): Promise<TResponse> {
        return axios.post<TResponse>(url, body)
            .then((response) => {
                const responseData = response.data;
                window.$response = responseData; // make the response data available to the automated testing system

                switch (responseData.ResultCode.ResultCode) {
                    case RESULT_CODES.SUCCESS:
                        if (responseData.RequestType === 'Begin' && responseData.PromoDetails) {
                            this.emit('ON_PROMO_RESULT', responseData.PromoDetails);
                        }
                        this.emit('ON_SUCCESSFUL_RESULT', responseData);
                        return responseData;
                    case RESULT_CODES.NEW_PLAYER:
                        this.emit('ON_SUCCESSFUL_RESULT', responseData);
                        return responseData;

                    case RESULT_CODES.NO_STAKE_OPTIONS_AVAILBLE:
                        return responseData;

                    case RESULT_CODES.TIME_KEEPER_LIMIT:
                    case RESULT_CODES.REALITY_CHECK_LIMIT:
                    case RESULT_CODES.REALITY_CHECK_AND_TIMEKEEPER_LIMIT:
                        if (responseData.RequestType === 'Begin') {
                            if (responseData.TimeKeeperLimit) {
                                this.emit('ON_TIMEKEEPER_RESULT', responseData.TimeKeeperLimit);
                            }

                            if (responseData.ResultCode.ResultCode !== RESULT_CODES.TIME_KEEPER_LIMIT) {
                                this.emit('ON_REALITYCHECK_RESULT', this.realityCheckDuration);
                            }
                        }
                        throw responseData;

                    case RESULT_CODES.INTERNATIONAL_NO_CURRENT_SESSION:
                        this.emit('ON_NOSESSION_ERROR', responseData);
                        throw responseData;

                    case RESULT_CODES.BONUS_IN_PLAY:
                        this.emit('ON_BONUSINPLAY_ERROR');
                        throw responseData;

                    case RESULT_CODES.BALANCE_TOO_LOW:
                        this.emit('ON_LOWBALANCE_ERROR');
                        throw responseData;

                    case RESULT_CODES.NOT_AUTHORISED:
                        this.emit('ON_NOTAUTHORISED_ERROR', responseData);
                        throw responseData;

                    case RESULT_CODES.GAME_UNAVAILABLE:
                        this.emit('ON_GAME_UNAVAILABLE', responseData);
                        throw responseData;

                    case RESULT_CODES.IN_COOLOFF_WINDOW:
                        this.emit('ON_COOLOFF_WINDOW_HIT');
                        throw responseData;

                    case RESULT_CODES.TIME_LIMIT_REACHED:
                        this.emit('ON_TIME_LIMIT_REACHED_WINDOW_HIT');
                        throw responseData;

                    case RESULT_CODES.GAME_IN_GAME_FREEZE:
                        this.emit('ON_GAME_IN_GAME_FREEZE');
                        throw responseData;

                    case RESULT_CODES.BINGO_SELF_EXCLUSION:
                        this.emit('ON_BINGO_SELF_EXCLUSION', responseData);
                        throw responseData;

                    case RESULT_CODES.ARCADE_SELF_EXCLUSION:
                        this.emit('ON_ARCADE_SELF_EXCLUSION', responseData);
                        throw responseData;

                    // expected errors for the game to handle
                    case RESULT_CODES.ACCOUNT_FAILURE:
                        this.emit('ON_NOTAUTHORISED_ERROR', responseData);
                        return responseData;
                    case RESULT_CODES.INTERNATIONAL_SESSION_ALREADY_ENDED:
                    case RESULT_CODES.INTERNATIONAL_STAKE_EXCEEDS_SESSION_LIMIT:
                    case RESULT_CODES.INTERNATIONAL_SESSION_ALREADY_EXISTS:
                    case RESULT_CODES.LOWER_STAKE_POSSIBLE:
                    case RESULT_CODES.USE_FREE_PLAY_FIRST:
                    case RESULT_CODES.FREE_PLAY_AWARDED:
                    case RESULT_CODES.NO_MORE_FREE_PLAY:
                        throw responseData;

                    default:
                        // any other errors should notify to the user
                        this.emit('ON_ERROR_TO_NOTIFY', responseData.ResultCode);
                        throw responseData;
                }
            })
            .catch((response) => {
                if (response.message !== undefined && response.message.toLowerCase().indexOf('network error') > -1) {
                    this.emit('ON_NETWORK_ERROR');
                }

                throw response;
            });
    }
}
